// #1679 — MiniMaxH3Director's prompt widget is derived from the node's in-memory
// builderState. A raw panel_set_widget write therefore appears to succeed briefly and is
// immediately regenerated by the Director editor. Refuse it before the generic write path
// can mutate the graph or await any object-info/network work.

/** The DaSiWa node whose prompt widget is regenerated by its Director editor. */
export const MINIMAX_H3_DIRECTOR_TYPE = "MiniMaxH3Director";

/** The one derived widget this guard covers. */
export const MINIMAX_H3_DIRECTOR_PROMPT_WIDGET = "prompt";

/**
 * "derived" only for the exact Director node type and the exact prompt widget name.
 * Every other node and every other MiniMax widget stays on the normal write path.
 *
 * @param {{type?: unknown}} node
 * @param {unknown} widgetName
 * @returns {"derived"|null}
 */
export function classifyMiniMaxH3DirectorWrite(node, widgetName) {
  const type = node && typeof node === "object" ? node.type : undefined;
  if (type !== MINIMAX_H3_DIRECTOR_TYPE) return null;
  return widgetName === MINIMAX_H3_DIRECTOR_PROMPT_WIDGET ? "derived" : null;
}

/**
 * Explain the silent-revert mechanism and the verified external override workaround.
 */
export function miniMaxH3DirectorPromptRefusal(widgetName, nodeId) {
  return (
    `panel_set_widget cannot drive "${widgetName}" on ${MINIMAX_H3_DIRECTOR_TYPE} node ${nodeId}: ` +
    `the prompt is a DERIVED widget regenerated from the node's in-memory builderState, so a ` +
    `direct write is silently reverted (#1679). Use the node's supported ` +
    `external_prompt_overwrite path instead: connect a PrimitiveNode STRING output to ` +
    `"external_prompt_overwrite", then set the PrimitiveNode's STRING value with ` +
    `panel_set_widget. The prompt write was refused before any graph mutation; other widgets ` +
    `and node types are unaffected.`
  );
}
